// Turns a voxel model's six side bitmaps into the bytes its material reads: a
// solid volume carved by the side silhouettes, each surviving voxel packed into
// four bytes holding six faces of five-bit palette index, with the top two
// alpha bits marking the voxel solid. Also encodes a palette as the one-row
// texel buffer the material's palette texture samples.
import type { RGBA } from "@big-mesh-studios/maths";
import { Bitmap, Dimensions3D, Vector3D } from "@big-mesh-studios/maths";
import {
  axisSides,
  dimensionAxes,
  dimensionKinds,
  facingAxis,
  sideAxes,
  sideDirections,
  sideKinds,
  type Axis,
  type Section,
  type Sides,
} from "./data";
import type { FaceSource } from "./mesh/mesher";
import type { Volume } from "./volume";

export type ViewSpec = {
  kind: keyof Sides;
  side: Bitmap;
  axis: Axis;
  fixedCoords: (px: number, py: number) => Vector3D;
};

// Right-handed coordinate system: +x right, +y up, +z out of the front face
// toward the viewer. The front face is at z = depth - 1 (facing the camera at
// +z) and the back face is at z = 0. Each view fixes the two coordinates its
// drawing spans, which way about `sideDirections` says, and leaves the one
// along the axis it looks down at zero for the caller to march.
const createViews = (dimensions: Dimensions3D, sides: Sides): ViewSpec[] =>
  sideKinds.map((kind) => {
    const [across, down] = sideAxes[kind];
    const [acrossAgainst, downAgainst] = sideDirections[kind];

    return {
      kind,
      side: sides[kind],
      axis: dimensionAxes[facingAxis[kind]],
      fixedCoords: (px, py) => {
        const at = Vector3D.create();

        at[dimensionAxes[across]] = acrossAgainst
          ? dimensions[across] - 1 - px
          : px;
        at[dimensionAxes[down]] = downAgainst ? dimensions[down] - 1 - py : py;

        return at;
      },
    };
  });

/** One face bounding a stretch of an axis: a drawing, and where its cells sit. */
interface Face {
  /**
   * Where the cell `(px, py)` of this drawing stands in the volume, with the
   * coordinate along the axis it looks down left at zero.
   */
  fixedCoords: (px: number, py: number) => Vector3D;
  side: Bitmap;
}

/** A stretch of one axis and the two faces that close it. */
interface Segment {
  axis: Axis;
  /** The first index of the stretch. */
  from: number;
  /** One past its last index. */
  to: number;
  /** The face at the low end of the stretch, and the one at the high end. */
  faces: [Face, Face];
}

/**
 * Every stretch of every axis, in the order the axes are named, each with the
 * pair of faces that carve it and colour the voxels at its ends.
 *
 * An axis with no section across it is one stretch, closed by the two sides
 * that look along it. Each section divides the stretch it falls in, and hands
 * the two halves the faces it reveals.
 */
const createSegments = (
  dimensions: Dimensions3D,
  sections: Section[],
  views: ViewSpec[],
): Segment[] => {
  const viewByKind = new Map(views.map((view) => [view.kind, view]));
  const segments: Segment[] = [];

  for (const dimension of dimensionKinds) {
    const [lowKind, highKind] = axisSides[dimension];
    const low = viewByKind.get(lowKind)!;
    const high = viewByKind.get(highKind)!;
    const extent = dimensions[dimension];
    const axis = dimensionAxes[dimension];

    const cuts = sections
      .filter((section) => section.axis === dimension)
      .map((section) => ({
        ...section,
        at: Math.min(Math.max(section.at, 0), extent),
      }))
      .sort((one, other) => one.at - other.at);

    let from = 0;
    let opening: Face = { fixedCoords: low.fixedCoords, side: low.side };

    for (const cut of cuts) {
      segments.push({
        axis,
        from,
        to: cut.at,
        faces: [opening, { fixedCoords: high.fixedCoords, side: cut.before }],
      });
      from = cut.at;
      opening = { fixedCoords: low.fixedCoords, side: cut.after };
    }

    segments.push({
      axis,
      from,
      to: extent,
      faces: [opening, { fixedCoords: high.fixedCoords, side: high.side }],
    });
  }

  return segments;
};

/**
 * Which drawing a voxel's face takes its colour from, at each index along an
 * axis: the low end of its stretch in `low`, the high end in `high`.
 */
const facesAlong = (extent: number, segments: Segment[]) => {
  const low: Bitmap[] = new Array(extent);
  const high: Bitmap[] = new Array(extent);

  for (const segment of segments) {
    for (let index = segment.from; index < segment.to; index++) {
      low[index] = segment.faces[0].side;
      high[index] = segment.faces[1].side;
    }
  }

  return { low, high };
};

export function solveVoxels(
  dimensions: Dimensions3D,
  sides: Sides,
  sections: Section[] = [],
  out: Uint8Array = new Uint8Array(
    dimensions.width * dimensions.height * dimensions.depth * 4,
  ),
): Uint8Array {
  const { height, width, depth } = dimensions;
  const outLength = width * height * depth * 4;
  if (out.length !== outLength) {
    throw new Error(`out.length expected to be ${outLength}`);
  }

  const calcTargetOffset = ({ x, y, z }: Vector3D) => {
    return (z * width * height + y * width + x) << 2;
  };

  const axisStride = {
    x: 4,
    y: width * 4,
    z: width * height * 4,
  };

  const views = createViews(dimensions, sides);

  // Start off with every voxel solid, for the silhouettes to carve away. Only
  // the alpha byte is read until the packing below, which writes all four.
  out.fill(255);

  const segments = createSegments(dimensions, sections, views);

  // Erase the silhouettes. A face carves the stretch of the axis it closes and
  // no further, so a cut is what lets one stretch be carved away where the next
  // is left standing.
  for (const segment of segments) {
    const stride = axisStride[segment.axis];

    for (const { side, fixedCoords } of segment.faces) {
      for (let y = 0; y < side.height; ++y) {
        const rowOffset = y * side.width;

        for (let x = 0; x < side.width; ++x) {
          if (side.data[rowOffset + x] !== Bitmap.EMPTY) {
            continue;
          }

          let offset =
            calcTargetOffset(fixedCoords(x, y)) + segment.from * stride;

          for (let i = segment.from; i < segment.to; ++i) {
            if (out[offset + 3] !== 0) {
              out[offset] = 0;
              out[offset + 1] = 0;
              out[offset + 2] = 0;
              out[offset + 3] = 0;
            }
            offset += stride;
          }
        }
      }
    }
  }

  // Pack each surviving voxel into the shader's 30-bit face-colour format: six
  // faces, five bits per colour index, with the top two alpha bits marking the
  // voxel solid. Each face takes its colour from the drawing that looks at it —
  // the side where the voxel's stretch of the axis runs to the edge of the box,
  // and the face a section reveals where it does not.
  const along = {
    x: facesAlong(
      width,
      segments.filter((segment) => segment.axis === "x"),
    ),
    y: facesAlong(
      height,
      segments.filter((segment) => segment.axis === "y"),
    ),
    z: facesAlong(
      depth,
      segments.filter((segment) => segment.axis === "z"),
    ),
  };

  for (let z = 0; z < depth; z++) {
    for (let y = 0; y < height; y++) {
      const py = height - 1 - y;

      for (let x = 0; x < width; x++) {
        const offset = (z * width * height + y * width + x) << 2;

        if (out[offset + 3] === 0) {
          continue;
        }

        // front: (x, py), back: (width-1-x, py), left: (z, py),
        // right: (depth-1-z, py), top: (x, z), bottom: (x, depth-1-z)
        const f = faceColourIndex(along.z.high[z], x, py);
        const b = faceColourIndex(along.z.low[z], width - 1 - x, py);
        const l = faceColourIndex(along.x.low[x], z, py);
        const r = faceColourIndex(along.x.high[x], depth - 1 - z, py);
        const t = faceColourIndex(along.y.high[y], x, z);
        const bo = faceColourIndex(along.y.low[y], x, depth - 1 - z);

        out[offset + 0] = f | ((b & 0b111) << 5);
        out[offset + 1] =
          ((b >> 3) & 0b11) | ((l & 0b11111) << 2) | ((r & 0b1) << 7);
        out[offset + 2] = ((r >> 1) & 0b1111) | ((t & 0b1111) << 4);
        out[offset + 3] = ((t >> 4) & 0b1) | ((bo & 0b11111) << 1) | 0b11000000;
      }
    }
  }

  return out;
}

/**
 * The palette index of the cell at (px, py) of `side`, which the packed format
 * holds in five bits. A solid voxel can still have an empty cell facing it, on
 * a face nothing has drawn on; those take index zero, the palette's black,
 * which is what the nearest-colour search this replaces also settled on.
 */
const faceColourIndex = (side: Bitmap, px: number, py: number): number => {
  const index = side.data[py * side.width + px];
  return index === Bitmap.EMPTY ? 0 : index;
};

/**
 * Writes the one palette index a voxel carries into all six of its faces, and
 * marks it solid.
 *
 * Six five-bit fields in four bytes leaves room for two whole and four split, so
 * this is where the layout lives rather than at each of the callers that need a
 * voxel to show one colour: a volume's own packing and an edit overriding a voxel
 * are the same write, and a second copy of the shifts is a second thing to be
 * wrong.
 *
 * @param offset Where the voxel's four bytes start.
 */
export const writePackedVoxel = (
  out: Uint8Array,
  offset: number,
  index: number,
): void => {
  out[offset + 0] = index | ((index & 0b111) << 5);
  out[offset + 1] =
    ((index >> 3) & 0b11) | ((index & 0b11111) << 2) | ((index & 0b1) << 7);
  out[offset + 2] = ((index >> 1) & 0b1111) | ((index & 0b1111) << 4);
  out[offset + 3] = ((index >> 4) & 0b1) | ((index & 0b11111) << 1) | SOLID;
};

/**
 * A box of voxels packed into the format its material reads, with no carving:
 * every voxel that has a palette index in it is solid, and all six of its faces
 * take that one index, because a volume gives a voxel one colour rather than a
 * colour for each face.
 *
 * The bit layout is the one `solveVoxels` writes, so a voxel reads the same
 * whichever of the two a model was built by.
 */
export function packVolume(volume: Volume): Uint8Array {
  const { dimensions, voxels } = volume;
  const { width, height, depth } = dimensions;
  const out = new Uint8Array(width * height * depth * 4);

  for (let z = 0; z < depth; z++) {
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const index = voxels[z * width * height + y * width + x];
        if (index === Bitmap.EMPTY) {
          continue;
        }

        writePackedVoxel(out, (z * width * height + y * width + x) << 2, index);
      }
    }
  }

  return out;
}

/** The palette as the material wants it: one row of texels, RGBA, in order. */
export function encodePalette(palette: readonly RGBA[]): Uint8Array {
  const data = new Uint8Array(palette.length * 4);
  palette.forEach(({ r, g, b, a }, i) => {
    const offset = i << 2;
    data[offset + 0] = r;
    data[offset + 1] = g;
    data[offset + 2] = b;
    data[offset + 3] = a;
  });
  return data;
}

/** The two alpha bits marking a voxel solid, which nothing else reads. */
const SOLID = 0b11000000;

/**
 * Where each face's five bits sit in a packed voxel, as the stretches of the
 * four bytes they run through: which byte, how far into it, and how many bits.
 *
 * A face is written as more than one stretch wherever its five bits do not fit
 * in a byte, and they are listed from the low end of the index upwards: three of
 * the six faces straddle two bytes, because six five-bit fields in four bytes
 * leaves room for two of them whole and the other four must share.
 *
 * The order the faces are named in is the order the six sides are written in, and
 * it is not the order `faceIndexOf` numbers them: a front face looks along +z and
 * so is face four, a left face along −x and so is face one. A table rather than
 * arithmetic is what makes that a lookup rather than a derivation nobody can
 * check by reading it.
 */
const FACE_FIELDS: ReadonlyArray<
  ReadonlyArray<readonly [byte: number, shift: number, width: number]>
> = [
  // 0, +x, the right side: one bit at the top of the second byte, four at the
  // bottom of the third
  [
    [1, 7, 1],
    [2, 0, 4],
  ],
  // 1, −x, the left side: five bits in the second
  [[1, 2, 5]],
  // 2, +y, the top side: four bits high in the third byte, one in the fourth
  [
    [2, 4, 4],
    [3, 0, 1],
  ],
  // 3, −y, the bottom side: five bits in the fourth
  [[3, 1, 5]],
  // 4, +z, the front side: five bits in the first
  [[0, 0, 5]],
  // 5, −z, the back side: three bits at the top of the first, two at the bottom
  // of the second
  [
    [0, 5, 3],
    [1, 0, 2],
  ],
];

/** The `width` bits at `shift` into a byte, which is the only mask there is. */
const maskAt = (shift: number, width: number): number =>
  (((1 << width) - 1) << shift) & 0xff;

/**
 * The packed volume read the way a mesher wants a box of voxels: a cell is solid
 * or it is not, and each of its faces has a colour of its own.
 *
 * The layout is the one this file writes, so a reader sits beside its writer
 * rather than restating the bits somewhere the writer does not reach.
 */
export function packedFaces(
  dimensions: Dimensions3D,
  voxels: Uint8Array,
): FaceSource {
  const { width, height } = dimensions;
  const offsetAt = (x: number, y: number, z: number) =>
    (z * width * height + y * width + x) << 2;

  return {
    solid: (x, y, z) => (voxels[offsetAt(x, y, z) + 3] & SOLID) !== 0,

    colour: (x, y, z, face) => {
      const offset = offsetAt(x, y, z);
      let index = 0;
      let placed = 0;

      for (const [byte, shift, width] of FACE_FIELDS[face]) {
        index |=
          ((voxels[offset + byte] & maskAt(shift, width)) >>> shift) << placed;
        placed += width;
      }

      return index;
    },
  };
}
